class MessageQueue:
    def __init__(self):
        self.queue = []

    def send_message(self, message):
        self.queue.append(message)

    def receive_message(self):
        if self.is_empty():
            return None
        return self.queue.pop(0)

    def peek_message(self):
        if self.is_empty():
            return None
        return self.queue[0]

    def is_empty(self):
        return len(self.queue) == 0
