import Foundation

class LocalizationHelper {
    class func localize(key: String, count: Int? = nil) -> String {
        let bundlePath = (Bundle(for: LocalizationHelper.self).resourcePath! as NSString).appendingPathComponent("RelativeFormatter.bundle")
        let bundle = Bundle(path: bundlePath)

        var localizedString = bundle?.localizedString(forKey: key, value: nil, table: nil)

        if let count = count {
            // Handle pluralization based on the count parameter
            if let pluralizedString = bundle?.localizedString(forKey: key, value: nil, table: "Pluralizable", count: count) {
                localizedString = pluralizedString
            }
        }

        return localizedString ?? key
    }
}
```

