function fetchAndDisplayBlocks() {
  const { registerBlockType } = Blocks;
  const { PanelBody, TextControl } = Components;
  const { withSelect } = Data;

  const BlockList = withSelect((select) => {
    const { getBlockTypes } = select('core/blocks');
    const blockTypes = getBlockTypes();

    const blockList = blockTypes.map((block) => {
      return `- ${block.name}: ${block.description} (Category: ${block.category})`;
    });

    return blockList.join('\n');
  })(({ blockList }) => (
    <PanelBody title="Available Blocks">
      <TextControl
        label="List of Blocks"
        value={blockList}
        disabled
        rows={blockList.split('\n').length}
      />
    </PanelBody>
  ));

  registerBlockType('custom-blocks/block-list', {
    title: 'Block List',
    icon: 'list-view',
    category: 'widgets',
    edit: () => <BlockList />,
    save: () => null,
  });
}

