class NewsSpider(scrapy.Spider):
    name = 'news_spider'
    start_urls = ['http://www.example.com/news']

    def parse(self, response):
        article_urls = response.css('.article-link::attr(href)').extract()
        for url in article_urls:
            yield scrapy.Request(url=url, callback=self.parseArticle, headers=self.defaultHeaders)

    def parseArticle(self, response):
        title = response.css('.artTit::text').extract_first()
        content = "".join(response.css('.artText *::text').extract())
