use std::time::{Instant, Duration};

fn measure_execution_time<F, R>(func: F) -> (u128, String)
where
    F: FnOnce() -> R,
{
    let start_time = Instant::now();
    let _result = func();
    let duration = start_time.elapsed().as_nanos();
    let name = std::any::type_name::<F>().to_string();
    (duration, name)
}

fn main() {
    let (duration1, name1) = measure_execution_time(|| {
        // Function 1 to be measured
        // ...
    });
    eprintln!("{} ns : {}", duration1, name1);

    let (duration2, name2) = measure_execution_time(|| {
        // Function 2 to be measured
        // ...
    });
    eprintln!("{} ns : {}", duration2, name2);
}
