public class DataProcessor {
    private int[] data = new int[10];
    private int count = 0;
    private int sum = 0;
    private int max = Integer.MIN_VALUE;
    private int min = Integer.MAX_VALUE;

    // Method to update the maximum value in the data array
    private void updateMax(int n) {
        if (n > max) {
            max = n;
        }
    }

    // Method to update the minimum value in the data array
    private void updateMin(int n) {
        if (n < min) {
            min = n;
        }
    }

    // Method to calculate the average of the elements in the data array
    public double calculateAverage() {
        if (count < data.length) {
            data[count] = min;
            count++;
            sum += min;
        } else {
            sum -= data[count % data.length];
            data[count % data.length] = min;
            sum += min;
            count++;
        }
        return (double) sum / Math.min(count, data.length);
    }

    // Method to process the input and update data array
    public double processData(int n) {
        updateMax(n);
        updateMin(n);
        return calculateAverage();
    }
}
