            let _ = read_value!($next, char); // Consume the comma
            let y: i32 = read_value!($next, i32);
            Point { x, y }
        }
    };
    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Failed to parse input")
    };
}

struct Point {
    x: i32,
    y: i32,
}

fn main() {
    let input = "(-1, 5) (3, 7) (0, 0)";
    let mut iter = input.split_whitespace();

    let points: Vec<Point> = {
        let next = || iter.next().unwrap();
        vec![
            read_value!(next, Point),
            read_value!(next, Point),
            read_value!(next, Point),
        ]
    };

    for point in &points {
        println!("x: {}, y: {}", point.x, point.y);
    }
}
