    func logEvent(_ event: LogEvent) {
        loggedEvents.append(event)
    }

    func printLog() {
        for event in loggedEvents {
            var logString = "\(event.level): "
            if let tag = event.tag {
                logString += "[\(tag)] "
            }
            logString += "File: \(event.file), Function: \(event.function), Line: \(event.line)"
            print(logString)
        }
    }
}

