func createMove<T>(changes: [Change<T>], insertIndex: Int, deleteIndex: Int) -> Move<T>? {
    guard insertIndex < changes.count, deleteIndex < changes.count else {
        return nil // Invalid indices
    }

    guard let insertChange = changes[insertIndex].insert, let deleteChange = changes[deleteIndex].delete else {
        return nil // Missing insert or delete change
