using System;

namespace TesterCall.Services.Usage.Formatting.Interfaces
{
    public interface IAddContentService
    {
        void AddContent(string content);
    }

    public class TextContentService : IAddContentService
    {
        public void AddContent(string content)
        {
            Console.WriteLine($"Adding text content: {content}");
        }
    }

    public class ImageContentService : IAddContentService
    {
        public void AddContent(string content)
        {
            Console.WriteLine($"Adding image content: {content}");
        }
    }

    public interface IAddContentServiceFactory
    {
        IAddContentService CreateContentService(string contentType);
    }

    public class AddContentServiceFactory : IAddContentServiceFactory
    {
        public IAddContentService CreateContentService(string contentType)
        {
            if (contentType.Equals("text", StringComparison.OrdinalIgnoreCase))
            {
                return new TextContentService();
            }
            else if (contentType.Equals("image", StringComparison.OrdinalIgnoreCase))
            {
                return new ImageContentService();
            }
            else
            {
                throw new ArgumentException("Invalid content type");
            }
        }
    }

    public class Program
    {
        public static void Main()
        {
            IAddContentServiceFactory factory = new AddContentServiceFactory();

            IAddContentService textContentService = factory.CreateContentService("text");
            textContentService.AddContent("Sample text content");

            IAddContentService imageContentService = factory.CreateContentService("image");
            imageContentService.AddContent("Sample image content");
        }
    }
}
