impl ParsersImpl {
    fn next_offset(&self) -> Option<usize> {
        if self.current_offset < self.data.len() {
            let next_byte = self.data[self.current_offset];
            self.current_offset += 1;
            Some(next_byte as usize)
        } else {
            None
        }
    }
}
```

