interface GlobalHeadersType {
  header: string;
  value: string;
}

interface QueryConfigType {
  // query configuration properties
}

interface PackageInfoType {
  name: string;
  version: string;
}

function updateSourceTrackingHeader(
  globalHeaders: GlobalHeadersType[],
  queryConfig: QueryConfigType,
  packageInfo: PackageInfoType
): GlobalHeadersType[] {
  const updatedHeaders = globalHeaders.map(header => {
    if (header.header === 'Source-Tracking') {
      return {
        ...header,
        value: `${packageInfo.name};${packageInfo.version}`
      };
    }
    return header;
  });
  return updatedHeaders;
}
