func processArrayString(_ input: String) -> [String] {
    let brackets: CharacterSet = CharacterSet(charactersIn: "[]")
    let arrayString: CharacterSet = CharacterSet.whitespaces
    guard let representation = input.substring(with: input.range) else {
        return []
    }
