def mean(values):
    return float(sum(values)) / len(values)

def quantile(p):
    def bound_quantile(values):
        ix = int(len(values) * p)

        if len(values) % 2:
            return values[ix]
        elif ix < 1:
            return values[0]
        else:
            return mean(values[ix - 1:ix + 1])

